from solution import count_pairs


def test_issue_example():
    """Example: count_pairs([1,5,3,4,2],5,3) equals 2."""
    assert count_pairs([1, 5, 3, 4, 2], 5, 3) == 2  # 1+1=2 pairs: (1,4) 4-1=3, (2,5) 5-2=3


def test_issue_no_pairs_when_k_too_large():
    """Count distinct pairs with difference k is zero when no difference equals k."""
    assert count_pairs([1, 2, 3], 3, 10) == 0  # max diff 3-1=2 < 10, so 0+0=0


def test_issue_single_pair_exact_diff():
    """Count distinct pairs with difference k counts one pair with exact difference."""
    assert count_pairs([1, 5], 2, 4) == 1  # 5-1=4, so 1 pair


def test_issue_duplicate_values_counted_once():
    """Count only distinct pairs with difference k despite duplicated values."""
    assert count_pairs([1, 1, 2, 2], 4, 1) == 1  # values {1,2}, 2-1=1, so 1 pair not 2*2=4


def test_issue_k_zero_with_duplicates():
    """Count distinct pairs with difference k handles k equal to zero."""
    assert count_pairs([1, 1, 1, 2], 4, 0) == 1  # 1-1=0, one distinct value repeats, so 1


def test_issue_k_zero_without_duplicates():
    """Count distinct pairs with difference k is zero for k=0 with all distinct values."""
    assert count_pairs([1, 2, 3], 3, 0) == 0  # 2-2=0 needs repeat, none, so 0


def test_issue_empty_array():
    """Count distinct pairs with difference k in any array includes empty array as zero."""
    assert count_pairs([], 0, 1) == 0  # 0 elements, 0-0=0 pairs


def test_issue_single_element():
    """Count distinct pairs with difference k needs two elements so one element is zero."""
    assert count_pairs([42], 1, 5) == 0  # only 1 element, 0+0=0 pairs


def test_issue_negative_numbers():
    """Count distinct pairs with difference k in any array includes negative numbers."""
    assert count_pairs([-3, -2, -1], 3, 1) == 2  # 1+1=2 pairs: -2-(-3)=1, -1-(-2)=1


def test_contract_order_does_not_matter():
    """Distinct pairs with difference k are unordered so reversed input has same count."""
    assert count_pairs([2, 4, 3, 5, 1], 5, 3) == 2  # 1+1=2 pairs: 4-1=3, 5-2=3


def test_contract_consecutive_differences():
    """Distinct pairs with difference k counts every consecutive value differing by k."""
    assert count_pairs([1, 2, 3, 4], 4, 1) == 3  # 1+1+1=3 pairs: 2-1=1, 3-2=1, 4-3=1
